function randInt(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min }

function genName() {
  const s = surnames[randInt(0, surnames.length - 1)]
  const c1 = nameChars[randInt(0, nameChars.length - 1)]
  const c2 = Math.random() > 0.4 ? '' : nameChars[randInt(0, nameChars.length - 1)]
  return s + c1 + c2
}

function genEmail() {
  const prefix = genName() + randInt(100, 9999)
  const domain = emailDomains[randInt(0, emailDomains.length - 1)]
  return `${prefix}@${domain}`
}

function genPhone() {
  const prefixes = ['138','139','135','136','137','150','151','152','157','158','159','182','183','187','188','130','131','132','155','156','185','186','133','153','180','189','177','178','147']
  const p = prefixes[randInt(0, prefixes.length - 1)]
  return p + String(randInt(0, 99999999)).padStart(8, '0')
}

function genAddress() {
  const prov = provinces[randInt(0, provinces.length - 1)]
  const city = cities[randInt(0, cities.length - 1)]
  const dist = districts[randInt(0, districts.length - 1)]
  const street = streetPrefixes[randInt(0, streetPrefixes.length - 1)] + streetSuffixes[randInt(0, streetSuffixes.length - 1)]
  const num = randInt(1, 999)
  return `${prov}${city}${dist}${street}${num}号`
}

function genIdcard() {
  const areaCodes = ['110101','310101','440106','500101','510107','420106','330106','320106','610104','410105']
  const area = areaCodes[randInt(0, areaCodes.length - 1)]
  const year = randInt(1970, 2005)
  const month = String(randInt(1, 12)).padStart(2, '0')
  const day = String(randInt(1, 28)).padStart(2, '0')
  const seq = String(randInt(0, 999)).padStart(3, '0')
  const base = `${area}${year}${month}${day}${seq}`
  const weights = [7,9,10,5,8,4,2,1,6,3,7,9,10,5,8,4,2]
  const checkCodes = ['1','0','X','9','8','7','6','5','4','3','2']
  let sum = 0
  for (let i = 0; i < 17; i++) sum += parseInt(base[i]) * weights[i]
  const check = checkCodes[sum % 11]
  return base + check
}

function genBankcard() {
  const bins = ['622202','622203','622208','622848','622845','622846','622847','621700','621799','623668','621226','621288','622200','955880','955881','955882','955888']
  const bin = bins[randInt(0, bins.length - 1)]
  const len = randInt(16, 19)
  let card = bin
  while (card.length < len - 1) card += randInt(0, 9)
  let sum = 0
  let even = true
  for (let i = card.length - 1; i >= 0; i--) {
    let d = parseInt(card[i])
    if (even) { d *= 2; if (d > 9) d -= 9 }
    sum += d
    even = !even
  }
  const check = (10 - (sum % 10)) % 10
  return card + check
}

function genCompany() {
  const prefix = companyPrefixes[randInt(0, companyPrefixes.length - 1)]
  const industry = companyIndustries[randInt(0, companyIndustries.length - 1)]
  const type = companyTypes[randInt(0, companyTypes.length - 1)]
  return prefix + industry + type
}

function genIp() { return `${randInt(1, 223)}.${randInt(0, 255)}.${randInt(0, 255)}.${randInt(1, 254)}` }

function genUuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = (crypto.getRandomValues(new Uint8Array(1))[0] & 15) >> (c === 'x' ? 0 : 1)
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16)
  })
}

function genText() {
  const sentences = randInt(1, 5)
  let text = ''
  for (let s = 0; s < sentences; s++) {
    const words = randInt(5, 20)
    for (let w = 0; w < words; w++) {
      text += nameChars[randInt(0, nameChars.length - 1)]
    }
    text += '。'
  }
  return text
}

function process() {
  const count = Math.max(1, Math.min(100, mockCount.value || 10))
  const items = []
  for (let i = 0; i < count; i++) {
    switch (mockType.value) {
      case 'name': items.push(genName()); break
      case 'email': items.push(genEmail()); break
      case 'phone': items.push(genPhone()); break
      case 'address': items.push(genAddress()); break
      case 'idcard': items.push(genIdcard()); break
      case 'bankcard': items.push(genBankcard()); break
      case 'company': items.push(genCompany()); break
      case 'ip': items.push(genIp()); break
      case 'uuid': items.push(genUuid()); break
      case 'text': items.push(genText()); break
      default: items.push(genName())
    }
  }
  results.value = items
  copyAllState.value = 'idle'
}

function clear() { results.value = []; copyAllState.value = 'idle' }
function copyAll() {
  if (!results.value.length) return
  navigator.clipboard.writeText(results.value.join('\n')).then(() => { copyAllState.value = 'ok' }).catch(() => { copyAllState.value = 'fail' })
}
function copyOne(item) { navigator.clipboard.writeText(item) }
</script>

